sys_script_include.script:
var RoomUtilsClient = Class.create();
RoomUtilsClient.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getRoomDetails: function () {
        var room = new GlideRecord('u_room');
        if (room.get(this.getParameter('sysparm_room_id'))) {
            return JSON.stringify({
                room_number: room.getValue('u_room_number'),
                type: room.getValue('u_type'),
                capacity: room.getValue('u_capacity')
            });
        }
        return JSON.stringify({error: "Room not found"});
    }
});
